from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict | None, key: str) -> Any:
    if not record:
        return ""
    return record.get(key, "")


def _number(value: Any) -> Decimal | None:
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value).strip() or "0")
    except (InvalidOperation, ValueError):
        return None


def _greater(value: Any, bound: str) -> bool:
    number = _number(value)
    return number is not None and number > Decimal(bound)


def _at_least(value: Any, bound: str) -> bool:
    number = _number(value)
    return number is not None and number >= Decimal(bound)


def _at_most(value: Any, bound: str) -> bool:
    number = _number(value)
    return number is not None and number <= Decimal(bound)


def _lookup(
    tables: dict | None,
    table: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if not tables:
        return ""

    for row in tables.get(table, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in {"INSERT", "UPDATE"}:
            discount = _value(record, "DISC_PCT")
            if not (_at_least(discount, "0") and _at_most(discount, "100")):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        # ORD-002
        if event == "UPDATE":
            discount = _value(record, "DISC_PCT")
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if (
                _greater(discount, "20")
                and role != "MGR"
                and role != "ADMIN"
            ):
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in {"INSERT", "UPDATE"}:
            if not _greater(_value(record, "QTY"), "0"):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        # ORD-005
        if event == "INSERT":
            active = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
